/** Reads the game's JSON tool export into the same field shape as a decoded binary save. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    looksLikeToolExportJson, readToolExportJson
 * depends    —
 * used by    src/calculators/specs.generated, src/node/decode-save, src/save-decoder/index, src/save/access/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { z } from 'zod'

const rootSchema = z.record(z.string(), z.unknown())
const canonicalSchema = z.object({
  versionNumber: z.number().finite().optional(),
  researchLevel: z.array(z.number().finite()).optional(),
  battleHistory: z.union([z.array(z.unknown()), z.record(z.string(), z.unknown())]).optional(),
  upgradeWorkshopLevel: z.array(z.number().finite()).optional(),
  inventory: z.union([z.array(z.unknown()), z.record(z.string(), z.unknown())]).optional(),
}).passthrough().refine(root =>
  root.researchLevel !== undefined || root.battleHistory !== undefined
  || root.upgradeWorkshopLevel !== undefined || root.inventory !== undefined,
'JSON does not contain The Tower save data')

function normalize(value: unknown, depth = 0): unknown {
  if (depth > 100) throw new Error('JSON save nesting exceeds 100 levels')
  if (Array.isArray(value)) return value.map(item => normalize(item, depth + 1))
  if (!value || typeof value !== 'object') return value
  const result: Record<string, unknown> = {}
  for (const [key, item] of Object.entries(value)) {
    if (['__proto__', 'prototype', 'constructor'].includes(key)) throw new Error(`Unsafe JSON save key: ${key}`)
    const camel = key.charAt(0).toLowerCase() + key.slice(1)
    // The public export property has a different name from the binary backing field.
    const canonical = depth === 0 && camel === 'moduleInventory' ? 'inventory' : camel
    if (['__proto__', 'prototype', 'constructor'].includes(canonical)) throw new Error(`Unsafe JSON save key: ${canonical}`)
    if (Object.prototype.hasOwnProperty.call(result, canonical)) throw new Error(`Conflicting JSON save fields: ${canonical}`)
    Object.defineProperty(result, canonical, { value: normalize(item, depth + 1), enumerable: true, writable: true, configurable: true })
  }
  return result
}

/** Signature check only; use the decoder to validate the JSON and its game fields. */
export function looksLikeToolExportJson(bytes: Uint8Array): boolean {
  let offset = bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf ? 3 : 0
  while ([9, 10, 13, 32].includes(bytes[offset])) offset += 1
  return bytes[offset] === 123 || bytes[offset] === 91
}

/** Returns null for binary bytes; malformed or unrelated JSON fails explicitly. */
export function readToolExportJson(bytes: Uint8Array): Record<string, unknown> | null {
  if (!looksLikeToolExportJson(bytes)) return null
  const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes)
  const root: unknown = JSON.parse(text)
  rootSchema.parse(root)
  return canonicalSchema.parse(normalize(root))
}
